{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "The searchKey parameter is concatenated directly into a dynamic SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or String.escapeSingleQuotes to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "searchAccounts",
      "explanation": "The query does not enforce CRUD and FLS permissions, potentially allowing access to fields or records the user should not see.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce CRUD and FLS permissions."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "updatePhone",
      "explanation": "The SOQL query does not use WITH USER_MODE, so it ignores object and field permissions.",
      "remediation": "Add WITH USER_MODE to the SOQL query to enforce CRUD and FLS."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "updatePhone",
      "explanation": "The DML operation does not use 'update as user', so it ignores object and field permissions.",
      "remediation": "Use 'update as user' for the DML operation to enforce CRUD and FLS."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing mode violation",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "public without sharing class CaseHistoryController",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing rules. This can lead to unauthorized access to Case records.",
      "remediation": "Change the class declaration to 'with sharing' to enforce record-level sharing rules."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "SELECT Id, CaseNumber, Subject, Status, Description FROM Case",
      "explanation": "The SOQL query does not enforce CRUD and FLS checks. This can lead to unauthorized access to Case fields.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce CRUD and FLS checks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "ModifyAllData, ViewAllData",
      "explanation": "The permission set grants Modify All Data and View All Data, which are powerful system permissions that should only be granted to administrators or integration users with a clear need.",
      "remediation": "Remove Modify All Data and View All Data from the permission set unless absolutely necessary and justified."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest user exposure",
      "severity": "High",
      "file": "Catalog Site Profile.profile-meta.xml",
      "lines": "classAccesses",
      "explanation": "The guest user profile grants access to the PublicCatalogController class, which can be called by anyone on the internet through the site's Aura endpoint.",
      "remediation": "Remove the PublicCatalogController class from the guest user profile's classAccesses, or ensure it only returns data intended to be public and enforces USER_MODE."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS violation",
      "severity": "Medium",
      "file": "PublicCatalogController.cls",
      "lines": "getActiveProducts",
      "explanation": "The query in getActiveProducts does not enforce field-level security (FLS) for the Product2 object.",
      "remediation": "Use WITH SECURITY_ENFORCED in the SOQL query to enforce FLS."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing mode violation",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "class ContactSearchController",
      "explanation": "The class is declared 'without sharing', which ignores record-level sharing rules. This allows guest users to access Contact records they should not see.",
      "remediation": "Change the class declaration to 'with sharing' to enforce record-level sharing rules."
    },
    {
      "category": "C5",
      "title": "Guest user exposure",
      "severity": "High",
      "file": "Partner Site Profile.profile-meta.xml",
      "lines": "<apexClass>ContactSearchController</apexClass>",
      "explanation": "The ContactSearchController class is accessible to the guest user profile, allowing unauthenticated users to query Contact records.",
      "remediation": "Remove ContactSearchController from the classAccesses for the guest user profile or ensure the class enforces proper sharing rules."
    }
  ]
}
